cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Base premiums per item type (parallel price-list catalogue) ---
  it.todo("quotes an empty item list as 5 G (processing fee only)");
  it.todo("quotes a single plain sword as 105 G (100 G base + 5 G fee)");
  it.todo("quotes a single plain amulet as 65 G (60 G base + 5 G fee)");
  it.todo("quotes a single plain staff as 85 G (80 G base + 5 G fee)");
  it.todo("quotes a single plain potion as 45 G (40 G base + 5 G fee)");
  it.todo("quotes a single rune as 30 G (25 G base + 5 G fee)");
  it.todo("quotes a single moonstone as 30 G (25 G base + 5 G fee)");

  // --- Building block of 3 alike components ---
  it.todo("quotes 2 runes as 50 G base premium (no block)");
  it.todo("quotes 3 runes as 60 G base premium (block applies)");
  it.todo("quotes 4 runes as 100 G base premium (no block -- block requires exactly 3)");
  it.todo("quotes 7 runes as 175 G base premium (no block -- 7 is not exactly 3)");

  // --- "Alike" means exactly the same type, not the same family ---
  it.todo("quotes 2 runes + 1 moonstone as 75 G base premium (no block: different types)");
  it.todo("quotes 3 runes + 3 moonstones as 120 G base premium (two separate blocks of the same type)");

  // --- Item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge to a cursed sword's base premium (100 G -> 150 G base)");
  it.todo("adds a 30 % high-enchantment surcharge to a sword with enchantment 5 (threshold met)");
  it.todo("adds no high-enchantment surcharge to a sword with enchantment 4 (below threshold)");
  it.todo("adds both curse and high-enchantment surcharges to a cursed sword with enchantment 5");
  it.todo("applies item-specific surcharges only to the affected item: cursed sword + plain amulet -> 210 G before policy modifiers and fee");

  // --- Policy-wide modifiers ---
  it.todo("applies the 20 % loyalty discount to the policy base premium for a customer with exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount for a customer with 1 year with MHPCO");
  it.todo("applies the 10 % first-insurance surcharge on the policy base premium");
  it.todo("applies the 15 % follow-up-contract discount to every quote after the customer's first");
  it.todo("applies the first-insurance surcharge to a follow-up contract too (each quoted item is a first insurance)");

  // --- Premium rounding in MHPCO's favour ---
  it.todo("rounds a premium of 197.5 G up to 198 G (MHPCO's favour)");
  it.todo("keeps intermediate premium amounts as fractions and rounds only the final premium");

  // --- Premium integration examples ---
  it.todo("quotes a newcomer's cursed steel sword (enchantment 3) as 165 G");
  it.todo("quotes a 3-year customer's second contract for a cursed sword (enchantment 7) as 160 G");

  // --- Insurance sum and cap ---
  it.todo("sets the cap for a single sword policy to 2000 G (2 x 1000 G insurance sum)");
  it.todo("sets the cap for a two-sword policy to 4000 G (insurance sum 2000 G)");
  it.todo("sets the cap for a sword + amulet policy to 3200 G (insurance sum 1600 G)");
  it.todo("sets the cap for a sword + 3 runes policy to 3500 G (insurance sum 1750 G -- block discount does not reduce the sum)");
  it.todo("bases the cap on the unmodified insurance value: cursed sword (premium 165 G) still has cap 2000 G");

  // --- Standard claim reimbursement ---
  it.todo("pays out 400 G for a steel sword with enchantment 3 damaged by 500 G (full reimbursement minus 100 G deductible)");
  it.todo("pays out 100 G for a rune damaged by 200 G (no enchantment or material, so no special clause)");

  // --- Claim special clauses ---
  it.todo("pays out 400 G for a steel sword with enchantment 9 damaged by 1000 G (50 % clause, then deductible)");
  it.todo("pays out 700 G for a dragon-material sword with enchantment 5 damaged by 800 G (full reimbursement, then deductible)");
  it.todo("pays out 400 G for a dragon-material sword with enchantment 9 damaged by 1000 G (50 % rule wins, then deductible)");
  it.todo("pays out 400 G for a dragon-material sword with exactly enchantment 8 damaged by 1000 G (threshold met)");

  // --- Deductible per damage event ---
  it.todo("applies the 100 G deductible once per damaged item: sword 500 G + amulet 300 G -> payout 600 G");
  it.todo("treats two sword damage entries on a two-sword policy as separate damages, each with its own deductible");

  // --- Payout rounding in MHPCO's favour ---
  it.todo("rounds a payout of 350.5 G down to 350 G (MHPCO's favour)");

  // --- Cap exhaustion across successive claims ---
  it.todo("reports remainingCap 600 G after a first 1500 G claim on a sword policy (payout 1400 G)");
  it.todo("limits a second 1500 G claim to the remaining cap: payout 600 G, remainingCap 0 G");

  // --- Rejections (observable contract: the domain throws an Error; the CLI exits non-zero and writes the message to stderr) ---
  it.todo("throws an Error when a quote contains an unknown item type (e.g. broomstick)");
  it.todo("throws an Error when a claim damages an item type that is not part of the policy (amulet damaged, only a sword insured)");
  it.todo("throws an Error when a claim damages an unknown item type");
  it.todo("throws an Error when a claim contains more damage entries of a type than the policy covers (two sword damages, one sword insured)");
  it.todo("throws an Error when a claim contains a damage entry with a negative amount (-200)");

  // --- CLI adapter (src/cli.ts): JSON in, JSON out ---
  it.todo("CLI reads the schema example scenario from stdin and writes {results:[{premium},{payout,remainingCap}]} to stdout");
  it.todo("CLI processes steps sequentially so a claim step resolves its policy by the quote step's zero-based index");
  it.todo("CLI exits with a non-zero status and writes an error description to stderr for an unknown quote item type, writing no results to stdout");
  it.todo("CLI exits with a non-zero status and writes an error description to stderr for an invalid claim");
});
EOF
pnpm test 2>&1 | tail -15

