/** An item's share of the policy premium: its base premium plus its own risk surcharges. */
function surchargedBasePremiumOf({ item, basePremium }: ItemBasePremium): number {
  return basePremium * (1 + itemRiskSurchargeRateOf(item));
}

/**
 * What the office holds the items of one policy to be worth: every item's base
 * premium, each with that item's own risk surcharges already added. This is the
 * item side of the premium -- it depends on the items alone and knows nothing of
 * who brings them.
 */
function insuredItemsPremiumOf(items: Item[]): number {
  return groupAlikeItems(items)
    .flatMap(itemBasePremiumsOf)
    .reduce((total, itemBasePremium) => total + surchargedBasePremiumOf(itemBasePremium), 0);
}

