const LOYALTY_DISCOUNT_RATE = -0.2;
const LOYALTY_YEARS = 2;

/** The office calls a customer long-standing after 2 years of business. */
function isLongStandingCustomer(customer: Customer): boolean {
  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
}

/**
 * One clause of the office's schedule of policy-wide terms: the standing it looks
 * for in the customer's record, and the rate it then applies to the policy base
 * premium. Surcharges carry a positive rate, discounts a negative one -- the
 * office's own arithmetic, which adds its policy-wide rates together.
 */
interface PolicyModifierClause {
  appliesTo: (customer: Customer) => boolean;
  modifierRate: number;
}

/** The office's schedule of terms earned by the customer's record. */
const CUSTOMER_RECORD_CLAUSES: PolicyModifierClause[] = [
  { appliesTo: isLongStandingCustomer, modifierRate: LOYALTY_DISCOUNT_RATE },
];

/**
 * Terms earned by the customer's record are charged on the policy base premium --
 * the sum of all item base premiums -- never on a single item. A customer
 * entitled to several of them has their rates added together.
 */
function customerRecordRateOf(customer: Customer): number {
  return CUSTOMER_RECORD_CLAUSES.filter((clause) => clause.appliesTo(customer)).reduce(
    (rate, clause) => rate + clause.modifierRate,
    0,
  );
}

