const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

/**
 * Every policy-wide term the office rates on the policy base premium, for this
 * customer: what their record earns them, plus what the office charges everyone.
 */
function policyModifierRateOf(customer: Customer): number {
  return customerRecordRateOf(customer) + FIRST_INSURANCE_SURCHARGE_RATE;
}

/**
 * What the office charges this customer for covering those items: what the items
 * themselves are worth, adjusted by the policy-wide terms the customer's record
 * earns them, with the processing fee added at the very end.
 */
function policyPremiumOf(customer: Customer, itemRating: ItemRating): number {
  const { policyBasePremium, itemRiskSurcharges } = itemRating;
  const policyModifiers = policyBasePremium * policyModifierRateOf(customer);
  return policyBasePremium + itemRiskSurcharges + policyModifiers + PROCESSING_FEE;
}

export function quote(customer: Customer, items: Item[]): number {
  return policyPremiumOf(customer, itemRatingOf(items));
}

