export interface Customer {
  yearsWithMHPCO: number;
}

/** An item a customer brings to be insured, as the office records it. */
export interface Item {
  type: string;
  material?: string;
  cursed?: boolean;
  enchantment?: number;
}

const PROCESSING_FEE = 5;

/**
 * How the office classes an item on its price list. Main items each have a row of
 * their own; components share a single uniform rate, and the office's
 * building-block offer is written for components alone.
 */
type PriceListClass = "main item" | "component";

/** One row of the MHPCO price list: what the office charges to insure one such item. */
interface PriceListEntry {
  class: PriceListClass;
  basePremium: number;
}

const COMPONENT_BASE_PREMIUM = 25;

/**
 * The MHPCO price list, as posted at the counter: every kind of item the office
 * recognises, and what it charges for one of them. An item type absent from the
 * list is one the office does not insure.
 */
const PRICE_LIST: Record<string, PriceListEntry> = {
  sword: { class: "main item", basePremium: 100 },
  amulet: { class: "main item", basePremium: 60 },
  staff: { class: "main item", basePremium: 80 },
  potion: { class: "main item", basePremium: 40 },
  rune: { class: "component", basePremium: COMPONENT_BASE_PREMIUM },
  moonstone: { class: "component", basePremium: COMPONENT_BASE_PREMIUM },
};

/** The price list's row for the given item type. */
function priceListEntryOf(type: string): PriceListEntry {
.....
    modifierRate: LOYALTY_DISCOUNT_RATE,
  },
  { appliesTo: isFollowUpContract, modifierRate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
];

/**
 * Every policy-wide term the office rates on the policy base premium -- the sum of
 * all item base premiums -- never on a single item: whichever scheduled terms the
 * circumstances of this contract earn, the office adding their rates together.
 */
function policyModifierRateOf(circumstances: PolicyCircumstances): number {
  return POLICY_MODIFIER_CLAUSES.filter((clause) => clause.appliesTo(circumstances)).reduce(
    (rate, clause) => rate + clause.modifierRate,
    0,
  );
}

/**
 * What the items and the contract's circumstances come to before the office writes
 * the figure down: what the items themselves are worth, adjusted by the policy-wide
 * terms the circumstances earn, with the processing fee added at the very end. Kept
 * as an exact fraction -- the office rounds the premium and nothing on the way to it.
 */
function exactPolicyPremiumOf(itemRating: ItemRating, circumstances: PolicyCircumstances): number {
  const { policyBasePremium, itemRiskSurcharges } = itemRating;
  const modifierRate = policyModifierRateOf(circumstances);
  return (
    policyBasePremium + itemRiskSurcharges + policyBasePremium * modifierRate + PROCESSING_FEE
  );
}

/**
 * A premium is money owed to the office, so rounding it to whole G in the office's
 * own favour means rounding up. (The office's other rounded amount, a payout, is
 * money it hands out, and its favour points the other way there.)
 */
function premiumRoundedInMHPCOsFavour(exactPremium: number): number {
  return Math.ceil(exactPremium);
}

/**
 * The premium the office charges for covering those items under this contract: what
 * the terms come to, rounded to whole G in the office's favour. The office quotes
 * whole G, so rounding is part of the premium it decides on and not a later dressing
 * up of the figure.
 */

