class Policy {
  private cap: number;

  constructor(readonly items: Item[]) {
    this.cap = CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items);
  }

  get remainingCap(): number {
    return this.cap;
  }

  /** What the office pays out on one damage report, over all the items damaged. */
  payoutFor(incident: Incident): number {
    const exactPayout = incident.damages.reduce(
      (payout, damage) => payout + reimbursementFor(damage, this.damagedItem(damage)),
      0,
    );
    return payoutRoundedInMHPCOsFavour(exactPayout);
  }

  /** The insured item a reported damage refers to. */
  private damagedItem(damage: Damage): Item {
    const item = this.items.find((insured) => insured.type === damage.itemType);
    if (item === undefined) {
      throw new Error(`the policy does not cover a ${damage.itemType}`);
    }
    return item;
  }
}

